(function(w){w.HOMEWORK_SET_DATA=w.HOMEWORK_SET_DATA||{};w.HOMEWORK_SET_DATA["unit22-trap-c2-basic-4"]={"id":"unit22-trap-c2-basic-4","unitId":"2-2","chapterIds":["2-2"],"unitType":"basic","group":"2-2단원 · 선지 변형 유형 · 인과","name":"기본 OX 4","level":"기본","revision":3,"resetReviewOnRevision":true,"originPage":"unit22","shuffleQuestions":true,"timedMode":"question","isTypePractice":true,"practiceMode":"trap","practiceCategory":"인과","parts":[{"name":"U22-H12-05-B2 · 사례로 확인할 수 있는 가격의 한계","items":[{"id":"U22-H12-05-B2","type":"ox","changed":"두 사례는 높은 가격을 낸 사람이 언제나 물건을 더 소중히 여긴다는 것을 보여 준다.","answer":"X","ask":"다음 설명이 이 문단의 중요한 내용과 같으면 O, 다르면 X를 고르세요.","why":"비싼 값을 낼 능력이 있다는 사실만으로 간절한 마음까지 알 수는 없다.\n근거: “셰익스피어 연극이나 야구 경기를 가장 간절하게 보고 싶어 하는 사람이라도 입장권을 살 만한 경제적 여유가 없을 수 있다.” “그리고 어떤 경우에는 최고 가격을 내고 입장권을 손에 넣은 사람이라도 그 경험의 가치를 전혀 높게 평가하지 않을 수도 있다.”","paragraphCount":1,"readingLabel":"12문단 · 핵심 읽기 5/5단계","sourceLabel":"줄 서기를 돈으로 살 수 있을까 · 12문단","passage":"[문단 전체 · 12문단]\n하지만 이러한 주장은 설득력이 없다. 우리의 목적이 사회적 효용을 극대화하는 것이라 할지라도, 자유 시장이 줄 서기보다 믿음직스럽지 않을 수도 있다. 어떤 재화에 기꺼이 가격을 지불하려는 것이 꼭 해당 재화의 가치를 높게 평가한다는 뜻은 아니기 때문이다. 시장 가격에는 자발적으로 지불하려는 마음만큼이나 지불할 수 있는 능력도 반영된다. 셰익스피어 연극이나 야구 경기를 가장 간절하게 보고 싶어 하는 사람이라도 입장권을 살 만한 경제적 여유가 없을 수 있다. 그리고 어떤 경우에는 최고 가격을 내고 입장권을 손에 넣은 사람이라도 그 경험의 가치를 전혀 높게 평가하지 않을 수도 있다.","referenceMode":"visible","disableAutoFocus":true,"requiresEvidence":false,"highlightEvidence":true,"originPage":"unit22","shortComparison":true,"focusQuotes":[{"id":"L12:5","text":"셰익스피어 연극이나 야구 경기를 가장 간절하게 보고 싶어 하는 사람이라도 입장권을 살 만한 경제적 여유가 없을 수 있다."},{"id":"L12:6","text":"그리고 어떤 경우에는 최고 가격을 내고 입장권을 손에 넣은 사람이라도 그 경험의 가치를 전혀 높게 평가하지 않을 수도 있다."}],"skills":["인과"],"evidence":{"title":"사례로 확인할 수 있는 가격의 한계","statement":"두 사례는 높은 가격을 낸 사람이 언제나 물건을 더 소중히 여기는 것은 아니라는 것을 보여 준다.","explanation":"비싼 값을 낼 능력이 있다는 사실만으로 간절한 마음까지 알 수는 없다.\n근거: “셰익스피어 연극이나 야구 경기를 가장 간절하게 보고 싶어 하는 사람이라도 입장권을 살 만한 경제적 여유가 없을 수 있다.” “그리고 어떤 경우에는 최고 가격을 내고 입장권을 손에 넣은 사람이라도 그 경험의 가치를 전혀 높게 평가하지 않을 수도 있다.”","valid":["L12:5","L12:6"],"sources":[{"id":"L12","title":"줄 서기를 돈으로 살 수 있을까","label":"12문단","sentences":[{"id":"L12:1","text":"하지만 이러한 주장은 설득력이 없다.","paragraph":0,"memberIds":["L12:1"],"topic":"필자는 11문단에서 예상한 시장 옹호자의 반론, 곧 “비싼 값을 내는 사람이 공연을 가장 원하므로 시장에 맡기자”는 주장에 설득력이 없다고 본다."},{"id":"L12:2","text":"우리의 목적이 사회적 효용을 극대화하는 것이라 할지라도, 자유 시장이 줄 서기보다 믿음직스럽지 않을 수도 있다.","paragraph":0,"memberIds":["L12:2"],"topic":"목표가 '모두의 만족을 최대로'라고 쳐도, 시장이 줄 서기보다 더 믿을 만하지 않을 수도 있다."},{"id":"L12:3","text":"어떤 재화에 기꺼이 가격을 지불하려는 것이 꼭 해당 재화의 가치를 높게 평가한다는 뜻은 아니기 때문이다.","paragraph":0,"memberIds":["L12:3"],"topic":"돈을 많이 낸다고 해서 꼭 그걸 더 좋아한다는 뜻은 아니기 때문이다."},{"id":"L12:4","text":"시장 가격에는 자발적으로 지불하려는 마음만큼이나 지불할 수 있는 능력도 반영된다.","paragraph":0,"memberIds":["L12:4"],"topic":"가격에는 '얼마나 사고 싶은지(마음)'뿐 아니라 '돈이 얼마나 있는지(능력)'도 들어 있다."},{"id":"L12:5","text":"셰익스피어 연극이나 야구 경기를 가장 간절하게 보고 싶어 하는 사람이라도 입장권을 살 만한 경제적 여유가 없을 수 있다.","paragraph":0,"memberIds":["L12:5"],"topic":"공연이나 경기를 가장 보고 싶은 사람도 표 살 돈이 없을 수 있다."},{"id":"L12:6","text":"그리고 어떤 경우에는 최고 가격을 내고 입장권을 손에 넣은 사람이라도 그 경험의 가치를 전혀 높게 평가하지 않을 수도 있다.","paragraph":0,"memberIds":["L12:6"],"topic":"반대로, 가장 비싼 표를 산 사람이 그 공연을 별로 좋아하지 않을 수도 있다."}]}]},"claimEdits":[{"start":33,"end":38,"before":"여긴다는 ","after":"여기는 것은 아니라는 "}],"progressiveComparison":true,"progressiveStep":5,"progressiveTotal":5,"progressiveLabel":"핵심 의미 확인","learningFocus":"사례로 확인할 수 있는 가격의 한계","hintGuide":"높은 가격을 낸 사람이 반드시 더 간절히 원하는지 확인하세요.","synthesis":true,"editorSourceVersion":"5598b59f09780cf945105eb0dbb724e823a22b376887f3b25b89145b75c26489"}]},{"name":"U22-H13-04-B1 · 관객의 행동을 보고 든 의문","items":[{"id":"U22-H13-04-B1","type":"ox","changed":"필자는 늦게 와서 일찍 떠나는 관객을 보며 야구를 정말 좋아하는지 의심했다.","answer":"O","ask":"형광펜 문장을 읽고, 다음 설명이 맞으면 O, 틀리면 X를 고르세요.","why":"경기를 오래 보지 않는 관객의 행동이 야구를 좋아한다는 마음과 맞지 않아 보였기 때문이다.\n근거: “예를 들어 나는 야구장에 늦게 도착해 비싼 관람석에 앉았다가 일찍 자리를 뜨는 사람들을 자주 목격한다.” “그럴 때면 그들이 야구를 얼마나 좋아하는지 의심스럽다.”","paragraphCount":1,"readingLabel":"13문단 · 핵심 읽기 4/5단계","sourceLabel":"줄 서기를 돈으로 살 수 있을까 · 13문단","passage":"[핵심 문장 · 13문단]\n예를 들어 나는 야구장에 늦게 도착해 비싼 관람석에 앉았다가 일찍 자리를 뜨는 사람들을 자주 목격한다. 그럴 때면 그들이 야구를 얼마나 좋아하는지 의심스럽다.","referenceMode":"visible","disableAutoFocus":true,"requiresEvidence":false,"highlightEvidence":true,"originPage":"unit22","shortComparison":true,"focusQuotes":[{"id":"L13:1","text":"예를 들어 나는 야구장에 늦게 도착해 비싼 관람석에 앉았다가 일찍 자리를 뜨는 사람들을 자주 목격한다."},{"id":"L13:2","text":"그럴 때면 그들이 야구를 얼마나 좋아하는지 의심스럽다."}],"skills":["인과"],"evidence":{"title":"관객의 행동을 보고 든 의문","statement":"필자는 늦게 와서 일찍 떠나는 관객을 보며 야구를 정말 좋아하는지 의심했다.","explanation":"경기를 오래 보지 않는 관객의 행동이 야구를 좋아한다는 마음과 맞지 않아 보였기 때문이다.\n근거: “예를 들어 나는 야구장에 늦게 도착해 비싼 관람석에 앉았다가 일찍 자리를 뜨는 사람들을 자주 목격한다.” “그럴 때면 그들이 야구를 얼마나 좋아하는지 의심스럽다.”","valid":["L13:1","L13:2"],"sources":[{"id":"L13","title":"줄 서기를 돈으로 살 수 있을까","label":"13문단","sentences":[{"id":"L13:1","text":"예를 들어 나는 야구장에 늦게 도착해 비싼 관람석에 앉았다가 일찍 자리를 뜨는 사람들을 자주 목격한다.","paragraph":0,"memberIds":["L13:1"],"topic":"예를 들어 필자는 야구장에서 이런 사람들을 자주 본다. 늦게 와서 비싼 자리에 앉았다가 일찍 가 버리는 사람들이다."},{"id":"L13:2","text":"그럴 때면 그들이 야구를 얼마나 좋아하는지 의심스럽다.","paragraph":0,"memberIds":["L13:2"],"topic":"그럴 때 필자는 '저 사람들, 야구를 정말 좋아하는 걸까?' 하고 의심한다."}]}]},"progressiveComparison":true,"progressiveStep":4,"progressiveTotal":5,"progressiveLabel":"관계 파악","learningFocus":"관객의 행동을 보고 든 의문","hintGuide":"관객들이 언제 와서 언제 떠났는지 확인하세요.","synthesis":false,"editorSourceVersion":"1aa4477469c876a594ba51f0474d878a9e7359b794bd8be557718c25945d593f"}]},{"name":"U22-H13-04-B2 · 가격으로 마음을 알기 어려운 이유","items":[{"id":"U22-H13-04-B2","type":"ox","changed":"가격에는 돈을 낼 능력이 빠지므로, 가격만으로 간절한 마음을 정확히 알기는 어렵다.","answer":"X","ask":"형광펜 문장을 읽고, 다음 설명이 맞으면 O, 틀리면 X를 고르세요.","why":"돈을 내고 싶은 마음뿐 아니라 실제로 가진 돈도 가격에 영향을 준다.\n근거: “시장 가격은 자발적으로 가격을 지불하려는 마음뿐만 아니라 능력도 반영하므로, 누가 특정 재화의 가치를 가장 높게 평가하는 사람인지 가려내기에는 불완전한 지표다.”","paragraphCount":1,"readingLabel":"13문단 · 핵심 읽기 4/5단계","sourceLabel":"줄 서기를 돈으로 살 수 있을까 · 13문단","passage":"[핵심 문장 · 13문단]\n시장 가격은 자발적으로 가격을 지불하려는 마음뿐만 아니라 능력도 반영하므로, 누가 특정 재화의 가치를 가장 높게 평가하는 사람인지 가려내기에는 불완전한 지표다.","referenceMode":"visible","disableAutoFocus":true,"requiresEvidence":false,"highlightEvidence":true,"originPage":"unit22","shortComparison":true,"focusQuotes":[{"id":"L13:5","text":"시장 가격은 자발적으로 가격을 지불하려는 마음뿐만 아니라 능력도 반영하므로, 누가 특정 재화의 가치를 가장 높게 평가하는 사람인지 가려내기에는 불완전한 지표다."}],"skills":["인과"],"evidence":{"title":"가격으로 마음을 알기 어려운 이유","statement":"가격에는 돈을 낼 능력도 들어가므로, 가격만으로 간절한 마음을 정확히 알기는 어렵다.","explanation":"돈을 내고 싶은 마음뿐 아니라 실제로 가진 돈도 가격에 영향을 준다.\n근거: “시장 가격은 자발적으로 가격을 지불하려는 마음뿐만 아니라 능력도 반영하므로, 누가 특정 재화의 가치를 가장 높게 평가하는 사람인지 가려내기에는 불완전한 지표다.”","valid":["L13:5"],"sources":[{"id":"L13","title":"줄 서기를 돈으로 살 수 있을까","label":"13문단","sentences":[{"id":"L13:5","text":"시장 가격은 자발적으로 가격을 지불하려는 마음뿐만 아니라 능력도 반영하므로, 누가 특정 재화의 가치를 가장 높게 평가하는 사람인지 가려내기에는 불완전한 지표다.","paragraph":0,"memberIds":["L13:5"],"topic":"가격에는 마음과 돈(능력)이 같이 들어 있다. 그래서 가격만 보고는 누가 가장 좋아하는지 정확히 알 수 없다. 가격은 정확하지 않은 자(불완전한 지표)다."}]}]},"claimEdits":[{"start":10,"end":20,"before":"능력이 빠지므로, ","after":"능력도 들어가므로, "}],"progressiveComparison":true,"progressiveStep":4,"progressiveTotal":5,"progressiveLabel":"관계 파악","learningFocus":"가격으로 마음을 알기 어려운 이유","hintGuide":"가격에 반영되는 것이 사고 싶은 마음뿐인지 확인하세요.","synthesis":false,"editorSourceVersion":"bdae6ee7b9b4ed3af96ea5a4737743bf56bd61e6cbcb2238397ff2a1dd82edcd"}]},{"name":"U22-H15-04-B1 · 시장이 항상 더 낫지 않은 이유","items":[{"id":"U22-H15-04-B1","type":"ox","changed":"시장과 줄 서기는 상황마다 결과가 달라서, 시장이 언제나 더 낫다고 할 수 없다.","answer":"O","ask":"형광펜 문장을 읽고, 다음 설명이 맞으면 O, 틀리면 X를 고르세요.","why":"물건을 가장 소중히 여기는 사람에게 주는 데 시장이 나을 때도, 줄 서기가 나을 때도 있다.\n근거: “따라서 줄 서기보다 시장 논리가 더 낫다는 공리주의자의 입장은 우연에 상당한 지배를 받는다.” “그 가치를 가장 높게 평가하는 사람에게 재화를 분배하는 역할은 시장이 수행할 때도 있고 줄 서기가 수행할 때도 있기 때문이다.”","paragraphCount":1,"readingLabel":"15문단 · 핵심 읽기 4/5단계","sourceLabel":"줄 서기를 돈으로 살 수 있을까 · 15문단","passage":"[핵심 문장 · 15문단]\n따라서 줄 서기보다 시장 논리가 더 낫다는 공리주의자의 입장은 우연에 상당한 지배를 받는다. 그 가치를 가장 높게 평가하는 사람에게 재화를 분배하는 역할은 시장이 수행할 때도 있고 줄 서기가 수행할 때도 있기 때문이다.","referenceMode":"visible","disableAutoFocus":true,"requiresEvidence":false,"highlightEvidence":true,"originPage":"unit22","shortComparison":true,"focusQuotes":[{"id":"L15:1","text":"따라서 줄 서기보다 시장 논리가 더 낫다는 공리주의자의 입장은 우연에 상당한 지배를 받는다."},{"id":"L15:2","text":"그 가치를 가장 높게 평가하는 사람에게 재화를 분배하는 역할은 시장이 수행할 때도 있고 줄 서기가 수행할 때도 있기 때문이다."}],"skills":["인과"],"evidence":{"title":"시장이 항상 더 낫지 않은 이유","statement":"시장과 줄 서기는 상황마다 결과가 달라서, 시장이 언제나 더 낫다고 할 수 없다.","explanation":"물건을 가장 소중히 여기는 사람에게 주는 데 시장이 나을 때도, 줄 서기가 나을 때도 있다.\n근거: “따라서 줄 서기보다 시장 논리가 더 낫다는 공리주의자의 입장은 우연에 상당한 지배를 받는다.” “그 가치를 가장 높게 평가하는 사람에게 재화를 분배하는 역할은 시장이 수행할 때도 있고 줄 서기가 수행할 때도 있기 때문이다.”","valid":["L15:1","L15:2"],"sources":[{"id":"L15","title":"줄 서기를 돈으로 살 수 있을까","label":"15문단","sentences":[{"id":"L15:1","text":"따라서 줄 서기보다 시장 논리가 더 낫다는 공리주의자의 입장은 우연에 상당한 지배를 받는다.","paragraph":0,"memberIds":["L15:1"],"topic":"그러니 \"시장이 줄 서기보다 낫다\"는 공리주의자의 말은 맞을 때도 있고 틀릴 때도 있다. 상황에 따라 그때그때 달라진다(우연에 크게 좌우된다)."},{"id":"L15:2","text":"그 가치를 가장 높게 평가하는 사람에게 재화를 분배하는 역할은 시장이 수행할 때도 있고 줄 서기가 수행할 때도 있기 때문이다.","paragraph":0,"memberIds":["L15:2"],"topic":"가장 좋아하는 사람에게 물건을 잘 보내는 쪽이 어떤 때는 시장이고, 어떤 때는 줄 서기이기 때문이다."}]}]},"progressiveComparison":true,"progressiveStep":4,"progressiveTotal":5,"progressiveLabel":"관계 파악","learningFocus":"시장이 항상 더 낫지 않은 이유","hintGuide":"어떤 경우에도 시장이 더 잘 나누어 주는지 확인하세요.","synthesis":false,"editorSourceVersion":"16314da16348b52c6fddae1d247e44e342fda75c9fe5e1aa09760765b343498e"}]},{"name":"U22-H16-04-B1 · 이익만으로 판단하면 안 되는 이유","items":[{"id":"U22-H16-04-B1","type":"ox","changed":"어떤 물건에는 거래 이익 말고도 가치가 있어서, 이익만으로 판단하면 안 된다.","answer":"O","ask":"형광펜 문장을 읽고, 다음 설명이 맞으면 O, 틀리면 X를 고르세요.","why":"사는 사람과 파는 사람이 얻는 이익이 그 물건의 전부는 아니기 때문이다.\n근거: “즉 공리주의적 사고가 유일하게 중요한 견해는 아니라는 반박이다.” “어떤 재화는 구매자와 판매자에게 부여하는 효용을 넘어선 가치를 지닌다.”","paragraphCount":1,"readingLabel":"16문단 · 핵심 읽기 4/5단계","sourceLabel":"줄 서기를 돈으로 살 수 있을까 · 16문단","passage":"[핵심 문장 · 16문단]\n즉 공리주의적 사고가 유일하게 중요한 견해는 아니라는 반박이다. 어떤 재화는 구매자와 판매자에게 부여하는 효용을 넘어선 가치를 지닌다.","referenceMode":"visible","disableAutoFocus":true,"requiresEvidence":false,"highlightEvidence":true,"originPage":"unit22","shortComparison":true,"focusQuotes":[{"id":"L16:2","text":"즉 공리주의적 사고가 유일하게 중요한 견해는 아니라는 반박이다."},{"id":"L16:3","text":"어떤 재화는 구매자와 판매자에게 부여하는 효용을 넘어선 가치를 지닌다."}],"skills":["인과"],"evidence":{"title":"이익만으로 판단하면 안 되는 이유","statement":"어떤 물건에는 거래 이익 말고도 가치가 있어서, 이익만으로 판단하면 안 된다.","explanation":"사는 사람과 파는 사람이 얻는 이익이 그 물건의 전부는 아니기 때문이다.\n근거: “즉 공리주의적 사고가 유일하게 중요한 견해는 아니라는 반박이다.” “어떤 재화는 구매자와 판매자에게 부여하는 효용을 넘어선 가치를 지닌다.”","valid":["L16:2","L16:3"],"sources":[{"id":"L16","title":"줄 서기를 돈으로 살 수 있을까","label":"16문단","sentences":[{"id":"L16:2","text":"즉 공리주의적 사고가 유일하게 중요한 견해는 아니라는 반박이다.","paragraph":0,"memberIds":["L16:2"],"topic":"바로 '행복(효용)의 양만 따지는 생각이 전부는 아니다'라는 것이다."},{"id":"L16:3","text":"어떤 재화는 구매자와 판매자에게 부여하는 효용을 넘어선 가치를 지닌다.","paragraph":0,"memberIds":["L16:3"],"topic":"어떤 것은 사고파는 사람이 얻는 만족보다 더 큰 가치를 가진다."}]}]},"progressiveComparison":true,"progressiveStep":4,"progressiveTotal":5,"progressiveLabel":"관계 파악","learningFocus":"이익만으로 판단하면 안 되는 이유","hintGuide":"이익 외의 가치가 있다면 이익 하나만 보아도 되는지 생각해 보세요.","synthesis":false,"editorSourceVersion":"2c342a37706985ff2d4b00e798ab2c2708e11a84b5570257181685697f8afbb4"}]},{"name":"U22-H16-05-B1 · 이익 외에 살펴야 할 가치","items":[{"id":"U22-H16-05-B1","type":"ox","changed":"물건이나 서비스의 가치를 판단할 때는 사는 사람과 파는 사람의 이익 외에 다른 가치도 살펴야 한다.","answer":"O","ask":"다음 설명이 이 문단의 중요한 내용과 같으면 O, 다르면 X를 고르세요.","why":"어떤 물건과 서비스에는 거래 이익만으로 설명할 수 없는 가치가 있다.\n근거: “즉 공리주의적 사고가 유일하게 중요한 견해는 아니라는 반박이다.” “어떤 재화는 구매자와 판매자에게 부여하는 효용을 넘어선 가치를 지닌다.”","paragraphCount":1,"readingLabel":"16문단 · 핵심 읽기 5/5단계","sourceLabel":"줄 서기를 돈으로 살 수 있을까 · 16문단","passage":"[문단 전체 · 16문단]\n그런데 줄 서기보다 시장 논리를 옹호하는 공리주의자들의 주장은 더욱 근본적인 반박에 부딪히기 쉽다. 즉 공리주의적 사고가 유일하게 중요한 견해는 아니라는 반박이다. 어떤 재화는 구매자와 판매자에게 부여하는 효용을 넘어선 가치를 지닌다. 재화의 분배 방식은 재화가 지닌 본질의 일부일 수도 있다.","referenceMode":"visible","disableAutoFocus":true,"requiresEvidence":false,"highlightEvidence":true,"originPage":"unit22","shortComparison":true,"focusQuotes":[{"id":"L16:2","text":"즉 공리주의적 사고가 유일하게 중요한 견해는 아니라는 반박이다."},{"id":"L16:3","text":"어떤 재화는 구매자와 판매자에게 부여하는 효용을 넘어선 가치를 지닌다."}],"skills":["인과"],"evidence":{"title":"이익 외에 살펴야 할 가치","statement":"물건이나 서비스의 가치를 판단할 때는 사는 사람과 파는 사람의 이익 외에 다른 가치도 살펴야 한다.","explanation":"어떤 물건과 서비스에는 거래 이익만으로 설명할 수 없는 가치가 있다.\n근거: “즉 공리주의적 사고가 유일하게 중요한 견해는 아니라는 반박이다.” “어떤 재화는 구매자와 판매자에게 부여하는 효용을 넘어선 가치를 지닌다.”","valid":["L16:2","L16:3"],"sources":[{"id":"L16","title":"줄 서기를 돈으로 살 수 있을까","label":"16문단","sentences":[{"id":"L16:1","text":"그런데 줄 서기보다 시장 논리를 옹호하는 공리주의자들의 주장은 더욱 근본적인 반박에 부딪히기 쉽다.","paragraph":0,"memberIds":["L16:1"],"topic":"그런데 공리주의자의 주장에는 더 뿌리 깊은(근본적인) 문제가 있다."},{"id":"L16:2","text":"즉 공리주의적 사고가 유일하게 중요한 견해는 아니라는 반박이다.","paragraph":0,"memberIds":["L16:2"],"topic":"바로 '행복(효용)의 양만 따지는 생각이 전부는 아니다'라는 것이다."},{"id":"L16:3","text":"어떤 재화는 구매자와 판매자에게 부여하는 효용을 넘어선 가치를 지닌다.","paragraph":0,"memberIds":["L16:3"],"topic":"어떤 것은 사고파는 사람이 얻는 만족보다 더 큰 가치를 가진다."},{"id":"L16:4","text":"재화의 분배 방식은 재화가 지닌 본질의 일부일 수도 있다.","paragraph":0,"memberIds":["L16:4"],"topic":"그리고 '어떻게 나눠 주느냐'가 그 물건의 진짜 의미(본질)의 일부일 수도 있다."}]}]},"progressiveComparison":true,"progressiveStep":5,"progressiveTotal":5,"progressiveLabel":"핵심 의미 확인","learningFocus":"이익 외에 살펴야 할 가치","hintGuide":"거래 이익이 유일한 판단 기준인지 확인하세요.","synthesis":true,"editorSourceVersion":"df92c00370e4de90232197e5552d2410831e57458913ef8fec93c7289ba71d00"}]},{"name":"U22-H17-05-B1 · 무료 공연을 팔 때 생기는 문제","items":[{"id":"U22-H17-05-B1","type":"ox","changed":"무료 공연을 상품으로 팔면, 돈 없는 관객이 못 보는 것 외에 공연에서 잃는 것도 있다.","answer":"O","ask":"다음 설명이 이 문단의 중요한 내용과 같으면 O, 다르면 X를 고르세요.","why":"공연이 상품이 되면서 무엇인가 사라지므로, 관람 기회의 공정성만이 문제는 아니다.\n근거: “하지만 문제는 공정성만이 아니다.” “공립 극장의 무료 공연이 시장 상품으로 바뀌면 무언가가 사라진다.”","paragraphCount":1,"readingLabel":"17문단 · 핵심 읽기 5/5단계","sourceLabel":"줄 서기를 돈으로 살 수 있을까 · 17문단","passage":"[문단 전체 · 17문단]\n퍼블릭 시어터에서 주관하는 여름 셰익스피어 무료 공연에 관해 다시 한번 생각해 보자. 대변인은 대리 줄 서기에 반대하는 극장의 입장을 밝히면서 “우리는 사람들이 공연을 무료로 관람하기를 원한다.”라고 말했다. 하지만 그렇게 말한 이유는 무엇일까? 입장권이 사고팔린다고 해서 공연 관람이 어떻게 감소한다는 것일까? 물론 연극을 보고 싶지만 입장권을 구매할 경제적 여유가 없는 사람에게는 공연을 관람할 기회가 축소될 것이다. 하지만 문제는 공정성만이 아니다. 공립 극장의 무료 공연이 시장 상품으로 바뀌면 무언가가 사라진다. 그 상실의 결과는 가격 경쟁에서 밀린 사람들이 느끼는 실망만이 아니다.","referenceMode":"visible","disableAutoFocus":true,"requiresEvidence":false,"highlightEvidence":true,"originPage":"unit22","shortComparison":true,"focusQuotes":[{"id":"L17:6","text":"하지만 문제는 공정성만이 아니다."},{"id":"L17:7","text":"공립 극장의 무료 공연이 시장 상품으로 바뀌면 무언가가 사라진다."}],"skills":["인과"],"evidence":{"title":"무료 공연을 팔 때 생기는 문제","statement":"무료 공연을 상품으로 팔면, 돈 없는 관객이 못 보는 것 외에 공연에서 잃는 것도 있다.","explanation":"공연이 상품이 되면서 무엇인가 사라지므로, 관람 기회의 공정성만이 문제는 아니다.\n근거: “하지만 문제는 공정성만이 아니다.” “공립 극장의 무료 공연이 시장 상품으로 바뀌면 무언가가 사라진다.”","valid":["L17:6","L17:7"],"sources":[{"id":"L17","title":"줄 서기를 돈으로 살 수 있을까","label":"17문단","sentences":[{"id":"L17:1","text":"퍼블릭 시어터에서 주관하는 여름 셰익스피어 무료 공연에 관해 다시 한번 생각해 보자.","paragraph":0,"memberIds":["L17:1"],"topic":"처음의 무료 셰익스피어 공연으로 다시 돌아가 보자."},{"id":"L17:2","text":"대변인은 대리 줄 서기에 반대하는 극장의 입장을 밝히면서 “우리는 사람들이 공연을 무료로 관람하기를 원한다.”라고 말했다.","paragraph":0,"memberIds":["L17:2"],"topic":"대변인은 \"우리는 사람들이 공짜로 공연을 보기를 바란다.\"라고 했다."},{"id":"L17:3","text":"하지만 그렇게 말한 이유는 무엇일까?","paragraph":0,"memberIds":["L17:3"],"topic":"왜 그렇게 말했을까?"},{"id":"L17:4","text":"입장권이 사고팔린다고 해서 공연 관람이 어떻게 감소한다는 것일까?","paragraph":0,"memberIds":["L17:4"],"topic":"표를 사고판다고 해서 공연을 보는 일에서 뭐가 줄어든다는 걸까?"},{"id":"L17:5","text":"물론 연극을 보고 싶지만 입장권을 구매할 경제적 여유가 없는 사람에게는 공연을 관람할 기회가 축소될 것이다.","paragraph":0,"memberIds":["L17:5"],"topic":"물론 보고 싶지만 돈이 없는 사람은 공연을 볼 기회가 줄어든다."},{"id":"L17:6","text":"하지만 문제는 공정성만이 아니다.","paragraph":0,"memberIds":["L17:6"],"topic":"그런데 문제는 '불공평하다'는 것만이 아니다."},{"id":"L17:7","text":"공립 극장의 무료 공연이 시장 상품으로 바뀌면 무언가가 사라진다.","paragraph":0,"memberIds":["L17:7"],"topic":"모두를 위한 공짜 공연이 '사고파는 물건'이 되면 뭔가가 없어진다."},{"id":"L17:8","text":"그 상실의 결과는 가격 경쟁에서 밀린 사람들이 느끼는 실망만이 아니다.","paragraph":0,"memberIds":["L17:8"],"topic":"그 잃어버린 것은 돈 경쟁에서 진 사람들의 속상함만이 아니다."}]}]},"progressiveComparison":true,"progressiveStep":5,"progressiveTotal":5,"progressiveLabel":"핵심 의미 확인","learningFocus":"무료 공연을 팔 때 생기는 문제","hintGuide":"표를 못 산 사람의 실망 말고도 사라지는 것이 있다고 했는지 보세요.","synthesis":true,"editorSourceVersion":"d2b8a5a3eb55e4dfd5d3267689669ff402433f40ccad2cbb149251ff2d4532c6"}]},{"name":"U22-H18-05-B2 · 개인의 돈벌이가 된 무료 공연","items":[{"id":"U22-H18-05-B2","type":"ox","changed":"필자는 무료 공연으로 개인이 돈을 벌어도 시민의 축제라는 목적이 지켜진다고 본다.","answer":"X","ask":"다음 설명이 이 문단의 중요한 내용과 같으면 O, 다르면 X를 고르세요.","why":"시민을 위한 선물을 개인의 돈벌이 도구로 바꾸는 일이기 때문이다.\n근거: “본래 선물이어야 하는 행사로 입장료를 받거나 암표상이 이득을 취하게 허용하는 일은 이러한 취지에 어긋난다.” “이는 공공의 축제를 돈벌이, 즉 사적 이익을 취득하기 위한 도구로 바꾸는 행위다.”","paragraphCount":1,"readingLabel":"18문단 · 핵심 읽기 5/5단계","sourceLabel":"줄 서기를 돈으로 살 수 있을까 · 18문단","passage":"[문단 전체 · 18문단]\n퍼블릭 시어터는 무료 야외 공연을 대중의 축제이자 일종의 시민 축하 행사로 생각한다. 말하자면 시(市)가 스스로에게 베푸는 선물인 셈이다. 물론 좌석 수는 한정되어 있다. 정해진 저녁 시간에 시민 전체가 참석할 수는 없기 때문이다. 하지만 퍼블릭 시어터의 취지는 관람료 지불 능력과 전혀 관계없이 누구나 평등하게 셰익스피어 공연을 무료로 관람할 수 있게 하는 것이다. 본래 선물이어야 하는 행사로 입장료를 받거나 암표상이 이득을 취하게 허용하는 일은 이러한 취지에 어긋난다. 이는 공공의 축제를 돈벌이, 즉 사적 이익을 취득하기 위한 도구로 바꾸는 행위다.","referenceMode":"visible","disableAutoFocus":true,"requiresEvidence":false,"highlightEvidence":true,"originPage":"unit22","shortComparison":true,"focusQuotes":[{"id":"L18:6","text":"본래 선물이어야 하는 행사로 입장료를 받거나 암표상이 이득을 취하게 허용하는 일은 이러한 취지에 어긋난다."},{"id":"L18:7","text":"이는 공공의 축제를 돈벌이, 즉 사적 이익을 취득하기 위한 도구로 바꾸는 행위다."}],"skills":["인과"],"evidence":{"title":"개인의 돈벌이가 된 무료 공연","statement":"필자는 무료 공연으로 개인이 돈을 벌면 시민의 축제라는 목적이 훼손된다고 본다.","explanation":"시민을 위한 선물을 개인의 돈벌이 도구로 바꾸는 일이기 때문이다.\n근거: “본래 선물이어야 하는 행사로 입장료를 받거나 암표상이 이득을 취하게 허용하는 일은 이러한 취지에 어긋난다.” “이는 공공의 축제를 돈벌이, 즉 사적 이익을 취득하기 위한 도구로 바꾸는 행위다.”","valid":["L18:6","L18:7"],"sources":[{"id":"L18","title":"줄 서기를 돈으로 살 수 있을까","label":"18문단","sentences":[{"id":"L18:1","text":"퍼블릭 시어터는 무료 야외 공연을 대중의 축제이자 일종의 시민 축하 행사로 생각한다.","paragraph":0,"memberIds":["L18:1"],"topic":"극장은 이 무료 공연을 모두의 축제, 시민들의 잔치로 여긴다."},{"id":"L18:2","text":"말하자면 시(市)가 스스로에게 베푸는 선물인 셈이다.","paragraph":0,"memberIds":["L18:2"],"topic":"말하자면 도시가 시민들, 곧 자기 자신에게 주는 선물이다."},{"id":"L18:3","text":"물론 좌석 수는 한정되어 있다.","paragraph":0,"memberIds":["L18:3"],"topic":"물론 자리는 정해져 있다."},{"id":"L18:4","text":"정해진 저녁 시간에 시민 전체가 참석할 수는 없기 때문이다.","paragraph":0,"memberIds":["L18:4"],"topic":"그날 저녁에 모든 시민이 다 올 수는 없으니까."},{"id":"L18:5","text":"하지만 퍼블릭 시어터의 취지는 관람료 지불 능력과 전혀 관계없이 누구나 평등하게 셰익스피어 공연을 무료로 관람할 수 있게 하는 것이다.","paragraph":0,"memberIds":["L18:5"],"topic":"하지만 극장이 원래 하려던 것(취지)은 돈이 있든 없든 누구나 똑같이 공짜로 공연을 보게 하는 것이다."},{"id":"L18:6","text":"본래 선물이어야 하는 행사로 입장료를 받거나 암표상이 이득을 취하게 허용하는 일은 이러한 취지에 어긋난다.","paragraph":0,"memberIds":["L18:6"],"topic":"원래 선물이어야 할 행사에서 입장료를 받거나 암표상이 돈을 벌게 놔두면, 그 목적과 어긋난다."},{"id":"L18:7","text":"이는 공공의 축제를 돈벌이, 즉 사적 이익을 취득하기 위한 도구로 바꾸는 행위다.","paragraph":0,"memberIds":["L18:7"],"topic":"그건 모두의 축제를 개인의 돈벌이 수단(사적 이익의 도구)으로 바꿔 버리는 일이다."}]}]},"claimEdits":[{"start":19,"end":23,"before":"벌어도 ","after":"벌면 "},{"start":36,"end":42,"before":"지켜진다고 ","after":"훼손된다고 "}],"progressiveComparison":true,"progressiveStep":5,"progressiveTotal":5,"progressiveLabel":"핵심 의미 확인","learningFocus":"개인의 돈벌이가 된 무료 공연","hintGuide":"시민에게 주는 선물을 개인의 돈벌이로 바꾸어도 되는지 보세요.","synthesis":true,"editorSourceVersion":"daeb15569a3aa33439f5c452ad1bf9ace7466b3554f970317ae1d7f299c22c56"}]}]};})(window);
